mapper.select:
SELECT r.id, r.user_id, r.contractor_id, r.estimate_request_id, r.last_message, r.last_message_at, r.created_at, u.nickname AS user_nickname, c.company_name AS contractor_name FROM chat_rooms r JOIN users u ON u.id = r.user_id JOIN contractors c ON c.id = r.contractor_id WHERE r.user_id = #{userId} AND r.contractor_id = #{contractorId}
AND r.estimate_request_id = #{estimateRequestId}
AND r.estimate_request_id IS NULL
LIMIT 1

mapper.update:
UPDATE chat_rooms
   SET last_message = #{lastMessage},
       last_message_at = #{lastMessageAt}
 WHERE id = #{id}
